use super::*;
fn chi(x:u64,r:u64)->i8{if x==0{0}else if pow(x,(r-1)/2,r)==1{1}else{-1}}
fn root(r:u64,m:usize)->u64{(1..r).find(|&z|pow(z,m as u64,r)==1&&(1..m).all(|j|pow(z,j as u64,r)!=1)).unwrap()}
fn eval(v:&[u64],x:u64,r:u64)->u64{v.iter().rev().fold(0,|a,&b|(mul(a,x,r)+b)%r)}
fn signs(f:&Fold,y:u64,b:u64)->Vec<i8>{let mut t=b;(0..f.m).map(|_|{let s=chi((y+f.r-t)%f.r,f.r);t=mul(t,f.zeta,f.r);s}).collect()}
fn dense(r:u64,q:[u64;4])->Vec<u64>{let mut c=vec![1];for _ in 0..(r-1)/2{let mut v=vec![0;c.len()+3];for(i,&a)in c.iter().enumerate(){for(j,&b)in q.iter().enumerate(){v[i+j]=(v[i+j]+mul(a,b,r))%r}}c=v}c}
fn projected(f:&Fold,c:&[u64])->Vec<u64>{let mut out=vec![0;f.d+1];for(t,&v)in c.iter().step_by(f.m).enumerate(){let at=if t>f.d{t-f.d}else{t};out[at]=(out[at]+mul(f.m as u64,v,f.r))%f.r}out}
#[test]fn dense_projection_values_and_image_sets(){let(mut compilers,mut values,mut sets,mut strict,mut radius_mutations)=(0,0,0,0,0);
 for r in [7,13,17,31,41,97]{for m in 3..=8{if(r-1)%m as u64!=0||(r-1)/m as u64%2!=0{continue}let f=Fold::new(r,m,root(r,m),8,100).unwrap();let pairs:Vec<_>=(0..m).map(|l|Correlation::compile(&f,l,8,100).unwrap()).collect();let lags=if m==3{vec![[1,2]]}else{vec![[1,2],[1,3]]};let triples:Vec<_>=lags.iter().map(|&ls|TripleCorrelation::compile(&f,ls,8,100).unwrap()).collect();
  for t in &triples{let q=cubic(r,pow(f.zeta,t.lags[0]as u64,r),pow(f.zeta,t.lags[1]as u64,r));assert_eq!(t.coefficients(),projected(&f,&dense(r,q)));assert_eq!(t.reflected_coefficients,f.d/2);compilers+=1;}
  for y in 0..r{for b in [1,2,3]{let s=signs(&f,y,b);let z=pow(y,m as u64,r);let v=mul(z,pow(pow(b,m as u64,r),r-2,r),r);
   for t in &triples{assert_eq!(eval(&t.constraint(b,&s).unwrap(),z,r),0);if chi(b,r)==-1&&eval(t.coefficients(),v,r)!=t.observed(&s).unwrap(){radius_mutations+=1}values+=1;}
   let mut state=f.initial().unwrap();f.observe(&mut state,b,s.iter().copied().product()).unwrap();for p in &pairs{p.observe(&mut state,b,&s).unwrap();}let before=state.moments().count;
   let expected:Vec<_>=(0..r).filter(|&z|eval(state.polynomial(),z,r)==0&&triples.iter().all(|t|eval(&t.constraint(b,&s).unwrap(),z,r)==0)).collect();for t in &triples{t.observe(&mut state,b,&s).unwrap();}let got:Vec<_>=(0..r).filter(|&z|eval(state.polynomial(),z,r)==0).collect();assert_eq!(got,expected);assert!(got.contains(&z));if state.moments().count<before{strict+=1}sets+=1;
  }}
 }}assert!(strict>0);assert!(radius_mutations>0);println!("dense_compilers={compilers} orbit_values={values} exact_image_sets={sets} strict_over_all_pairs={strict} missing_radius_factor_rejections={radius_mutations}");
}
fn stream(f:&Fold,q:[u64;4])->Vec<u64>{let r=f.r;let h=(r-1)/2;let mut state=[pow(q[0],h,r),0,0];let mut out=vec![state[0]];for j in 0..r-1{let mut v=0;for i in 1..=3{let factor=(((h+1)as u128*i as u128+r as u128-(j+1)as u128)%r as u128)as u64;v=(v+mul(mul(factor,q[i],r),state[i-1],r))%r}let next=mul(v,pow(mul(q[0],j+1,r),r-2,r),r);state=[next,state[0],state[1]];if(j+1)%f.m as u64==0{out.push(next)}}out}
#[test]fn large_prefixes_and_domain(){let r=65537;let mut reflected=0;for m in [128,256,512]{let f=Fold::new(r,m,pow(3,(r-1)/m as u64,r),512,513).unwrap();let a=f.zeta;let b=pow(a,3,r);let q=cubic(r,a,b);let qi=cubic(r,pow(a,r-2,r),pow(b,r-2,r));let(front,_,_)=cubic_prefix(&f,q).unwrap();let(back,_,_)=cubic_prefix(&f,qi).unwrap();assert_eq!(front,stream(&f,q));assert_eq!(back,stream(&f,qi));let t=TripleCorrelation::compile(&f,[1,3],512,512).unwrap();assert!(t.karatsuba_calls>0&&t.newton_steps>0);reflected+=t.reflected_coefficients;}println!("large_cases=3 scalar_prefix_comparisons=6 reflected_high_coefficients={reflected}");
 let f=Fold::new(13,6,4,6,3).unwrap();assert!(matches!(TripleCorrelation::compile(&f,[1,3],5,2),Err(Error::Limit)));assert!(matches!(TripleCorrelation::compile(&f,[1,3],6,1),Err(Error::Limit)));for ls in [[0,1],[1,1],[1,6]]{assert!(TripleCorrelation::compile(&f,ls,6,2).is_err())}let odd=Fold::new(7,2,6,2,4).unwrap();assert!(matches!(TripleCorrelation::compile(&odd,[1,1],2,3),Err(Error::Domain)));let t=TripleCorrelation::compile(&f,[1,3],6,2).unwrap();assert!(t.constraint(0,&[1;6]).is_err());assert!(t.constraint(1,&[1;5]).is_err());assert!(t.constraint(1,&[2;6]).is_err());
}
#[test]fn reciprocal_pairs_split_or_retained(){let(mut distinct,mut split,mut retained)=(0,0,0);for(r,m)in[(17,4),(41,4),(97,4),(97,8)]{let f=Fold::new(r,m,root(r,m),8,100).unwrap();let ps:Vec<_>=(0..m).map(|l|Correlation::compile(&f,l,8,100).unwrap()).collect();let t=TripleCorrelation::compile(&f,[1,3],8,100).unwrap();for b in [1,2,3]{for y in 1..r{let yp=mul(mul(b,b,r),pow(y,r-2,r),r);if pow(y,m as u64,r)==pow(yp,m as u64,r){continue}let s=signs(&f,y,b);let sp=signs(&f,yp,b);assert_eq!(s.iter().copied().product::<i8>(),sp.iter().copied().product::<i8>());for p in &ps{assert_eq!(p.observed(&s).unwrap(),p.observed(&sp).unwrap())}distinct+=1;if t.observed(&s).unwrap()!=t.observed(&sp).unwrap(){split+=1}else{retained+=1}}}}assert!(split>0);assert!(retained>0);println!("distinct_reciprocal_cases={distinct} triple_split={split} still_equal={retained}");}
#[test]fn public_higher_recovery(){let(mut total,mut recovered,mut unresolved,mut replay,mut calls)=(0,0,0,0,0);
 for(r,p,a,b,base,m,zeta,rounds)in[(13,7,0,3,[1,2],3,3,6),(13,7,0,3,[1,2],6,4,6),(479,509,2,10,[3,68],2,478,20),(683,701,2,8,[2,106],11,root(683,11),8)]{
  let inner=PublicRecovery::new(p,a,b,r,base,m,zeta,64,300,64,[0,1],rounds,2000).unwrap();let extra:Vec<_>=(0..17.min(r)).collect();let single=SingleRecovery::new(inner,512,&extra).unwrap();let lags=if r==479{vec![]}else if m==3{vec![[1,2]]}else{vec![[1,3]]};let runner=HigherRecovery::new(single,&[1],&lags,2,64,300).unwrap();
  let targets:Vec<_>=if r==479{include_str!("../feature-native-monomial-recovery/recovery.tsv").lines().skip(1).map(|s|{let v:Vec<_>=s.split('\t').collect();let k=v[0].parse::<u64>().unwrap();(k,if k==0{None}else{Some([v[1].parse().unwrap(),v[2].parse().unwrap()])})}).collect()}else{let ks:Vec<_>=if r==13{(0..r).collect()}else{vec![0,1,2,3,7,11,17,31,47,83,127,191,257,341,509,681,682]};ks.into_iter().map(|k|{let mut c=Counts::default();(k,PublicRecovery::pair(runner.base.inner.multiple(k,&mut c)))}).collect()};
  for(k,target)in targets{total+=1;match runner.recover(target).unwrap(){FiberOutcome::Recovered{value,route,stats}=>{assert_eq!(value,k);recovered+=1;if route=="retained-signs"{replay+=1}calls+=stats.outer.source_calls},FiberOutcome::Unresolved{stats,..}=>{unresolved+=1;calls+=stats.outer.source_calls}}}
 }assert_eq!(total,63);println!("public_cases={total} recovered={recovered} unresolved={unresolved} retained_routes={replay} source_calls={calls}");}
